module fixed_point_subtractor (
    parameter Q = 4, N = 8,
    input [N-1:0] a, b,
    output [N-1:0] c
);

    reg [N-1:0] res;

    always @(*) begin
        if ($signed(a) > $signed(b))
            res = (a[N-2:0] - b[N-2:0]) + {{N-1{1'b0}}, ~a[N-1]};
        else if ($signed(a) < $signed(b))
            res = (b[N-2:0] - a[N-2:0]) + {{N-1{1'b0}}, ~b[N-1]};
        else
            res = 0;

        if (&res[N-2:0])
            res[N-1] = 1'b0;
    end

    assign c = res;

endmodule
